/**
 * Akari Level & Tagesrätsel-Generierung
 * 240 deterministisch generierte Kampagnen-Level in 4 Kapiteln (6×6, 8×8, 10×10, 12×12/14×14)
 * und synchrones Tagesrätsel.
 */



function getAkariCampaignLevel(levelIndex) {
    // 240 Level in 4 Kapiteln:
    // Kapitel 1 (0–59): Glühwürmchen (Level 1–25: 6×6 Easy, Level 26–45: 6×6 Medium, Level 46–60: 7×7 Easy)
    // Kapitel 2 (60–119): Laternenstadt (Level 61–90: 8×8 Easy, Level 91–120: 8×8 Medium)
    // Kapitel 3 (120–179): Lichtkuppel (Level 121–150: 10×10 Medium, Level 151–180: 10×10 Hard)
    // Kapitel 4 (180–239): Photonen-Palast (Level 181–210: 12×12 Medium, Level 211–240: 14×14 Hard)

    let size, difficulty;
    if (levelIndex < 25) {
        size = 6;
        difficulty = 'easy';
    } else if (levelIndex < 45) {
        size = 6;
        difficulty = 'medium';
    } else if (levelIndex < 60) {
        size = 7;
        difficulty = 'easy';
    } else if (levelIndex < 90) {
        size = 8;
        difficulty = 'easy';
    } else if (levelIndex < 120) {
        size = 8;
        difficulty = 'medium';
    } else if (levelIndex < 150) {
        size = 10;
        difficulty = 'medium';
    } else if (levelIndex < 180) {
        size = 10;
        difficulty = 'hard';
    } else if (levelIndex < 210) {
        size = 12;
        difficulty = 'medium';
    } else {
        size = 14;
        difficulty = 'hard';
    }

    const seed = 50000 + (levelIndex + 1) * 313;
    const generated = AkariGenerator.generatePuzzle({ size, difficulty, seed });

    return {
        id: levelIndex + 1,
        tier: difficulty,
        name: `Level ${levelIndex + 1} (${size}×${size})`,
        ...generated
    };
}

/**
 * Erzeugt das synchrone Akari-Tagesrätsel basierend auf dem Datum
 */
function getAkariDailyPuzzle(dateStr) {
    const seed = parseInt(dateStr.replace(/-/g, ''), 10) + 333;
    const date = new Date(dateStr);
    const isWeekend = (date.getDay() === 0 || date.getDay() === 6);

    // Werktags 8x8 Medium, Wochenende 10x10 Hard
    const size = isWeekend ? 10 : 8;
    const difficulty = isWeekend ? 'hard' : 'medium';

    const generated = AkariGenerator.generatePuzzle({ size, difficulty, seed });

    return {
        date: dateStr,
        name: `Tagesrätsel: Akari (${dateStr})`,
        tier: isWeekend ? 'Wochenende (Meister)' : 'Werktag',
        ...generated
    };
}

